// Pass through every CSV field unchanged and add normalized fields.
const row = $input.item.json;

const rawName = (row.Customer_Name || '').toString();
const rawType = (row.Subscription_Type || '').toString();
const rawNotes = (row.Dietary_Notes || '').toString();
const rawDate = (row.Signup_Date || '').toString();

function titleCase(s) {
  return s
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function ordinal(n) {
  const v = n % 100;
  if (v >= 11 && v <= 13) return n + 'th';
  switch (n % 10) {
    case 1: return n + 'st';
    case 2: return n + 'nd';
    case 3: return n + 'rd';
    default: return n + 'th';
  }
}

function humanDate(iso) {
  if (!iso) return '';
  const m = iso.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return iso;
  const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const monthIdx = parseInt(m[2], 10) - 1;
  const day = parseInt(m[3], 10);
  if (monthIdx < 0 || monthIdx > 11) return iso;
  return months[monthIdx] + ' ' + ordinal(day);
}

const Subscription_Type_Clean = rawType.trim();
const Customer_Name_Display = titleCase(rawName.trim());
const Signup_Date_Display = humanDate(rawDate.trim());
const notesTrimmed = rawNotes.trim();
const Has_Dietary_Notes = notesTrimmed.length > 0 && notesTrimmed.toLowerCase() !== 'none';

let Channel_Targets = [];
if (Subscription_Type_Clean === 'Specialty Tea') Channel_Targets = ['tea-fulfillment'];
else if (Subscription_Type_Clean === 'Cold-Pressed Juice') Channel_Targets = ['juice-prep'];
else if (Subscription_Type_Clean === 'Mixed Box') Channel_Targets = ['tea-fulfillment','juice-prep'];
else Channel_Targets = [];

return {
  json: {
    Order_ID: row.Order_ID,
    Customer_Name: row.Customer_Name,
    Subscription_Type: row.Subscription_Type,
    Dietary_Notes: row.Dietary_Notes,
    Signup_Date: row.Signup_Date,
    Customer_Email: row.Customer_Email,
    Customer_Name_Display,
    Signup_Date_Display,
    Subscription_Type_Clean,
    Has_Dietary_Notes,
    Channel_Targets
  }
};

